// Logs and verifies escalation delivery across authority tiers
const response = $input.first().json;

return [{
  json: {
    status: 'ESCALATION_RECORDED',
    escalation_id: response.data?.escalation_id,
    district: response.data?.district,
    state: response.data?.state,
    notified_users_count: response.data?.notified_users_count,
    notified_roles: response.data?.notified_roles,
    dispatched_at: response.data?.timestamp,
  }
}];
